package com.graduation.lab.domain;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.time.*;import java.util.*;public interface LabReservationRepository extends JpaRepository<LabReservation,Long>{@Query("select r from LabReservation r where r.labId=:lab and r.status in ('PENDING','APPROVED') and r.startTime < :end and r.endTime > :start")List<LabReservation> conflicts(@Param("lab")Long lab,@Param("start")LocalDateTime start,@Param("end")LocalDateTime end);List<LabReservation>findTop200ByUserIdOrderByStartTimeDesc(Long u);}